package com.lexiscan.extraction; import org.apache.poi.xwpf.extractor.XWPFWordExtractor; import org.apache.poi.xwpf.usermodel.XWPFDocument; import org.springframework.stereotype.Component; import java.nio.file.*; @Component public class DocxTextExtractor implements TextExtractor {public String extract(Path p)throws Exception{try(var d=new XWPFDocument(Files.newInputStream(p));var x=new XWPFWordExtractor(d)){return x.getText();}}}
